// Arithmetic loop plus recursive Fibonacci calls.
fmt := import("fmt")

fib := func(n) {
    if n < 2 { return n }
    a := 0
    b := 1
    for i := 2; i <= n; i++ {
        c := a + b
        a = b
        b = c
    }
    return b
}

sum := 0
for i := 0; i < 1400000; i++ {
    sum += (i * i) % 97
}

fibSum := 0
for i := 0; i < 30; i++ {
    fibSum += fib(i)
}

fmt.printf("sum=%d fibSum=%d\n", sum, fibSum)

