// Map churn followed by a list sort.
fmt := import("fmt")

insertion_sort := func(list) {
    n := len(list)
    for i := 1; i < n; i++ {
        key := list[i]
        j := i - 1
        for j >= 0 && list[j] > key {
            list[j+1] = list[j]
            j--
        }
        list[j+1] = key
    }
    return list
}

counts := {}
for i := 0; i < 45000; i++ {
    key := string(i % 60)
    if is_undefined(counts[key]) {
        counts[key] = 0
    }
    counts[key] += 1
}
keys := []
for k, v in counts {
    keys = append(keys, k)
}
keys = insertion_sort(keys)
total := 0
for k, v in counts {
    total += v
}

nums := []
for i := 0; i < 1600; i++ {
    nums = append(nums, (i * 7919) % 10007)
}
nums = insertion_sort(nums)

fmt.printf("keys=%d maptotal=%d sorted_first=%d sorted_last=%d\n",
    len(keys), total, nums[0], nums[len(nums)-1])

